import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        R = int(next(iterator))
        C = int(next(iterator))
        X = int(next(iterator))

        A = []
        for r in range(R):
            row = []
            for c in range(C):
                row.append(int(next(iterator)))
            A.append(row)

        B = []
        for r in range(R):
            row = []

            for c in range(C):
                row.append(int(next(iterator)))

            B.append(row)

        possible = True

        for r in range(R):
            for c in range(C):
                diff = A[r][c] - B[r][c]
                if diff % X != 0:
                    possible = False
                    break
            if not possible:
                break

        if possible:
            sum_A = 0
            sum_B = 0
            for r in range(R):
                for c in range(C):
                    sum_A += A[r][c]
                    sum_B += B[r][c]

            if sum_A % X != sum_B % X:
                possible = False

        if possible:
            print("Yes")
        else:
            print("No")

if __name__ == "__main__":
    solve()
